  ],
  "key_assumptions": [
    {
      "assumption": "The environmental impact of large-scale AI training is immediate and irreversible at the 100-megawatt threshold.",
      "if_wrong": "If ecological damage is incremental or reversible, the case for rigid, hardware-level physical ceilings becomes significantly weaker."
